import{_ as a,c as o,o as s,ag as i}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"A02 — IAM groups, policies and roles","description":"","frontmatter":{},"headers":[],"relativePath":"practice/aws/associate-02.md","filePath":"practice/aws/associate-02.md"}'),r={name:"practice/aws/associate-02.md"};function n(t,e,c,l,d,p){return s(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="a02-—-iam-groups-policies-and-roles" tabindex="-1">A02 — IAM groups, policies and roles <a class="header-anchor" href="#a02-—-iam-groups-policies-and-roles" aria-label="Permalink to “A02 — IAM groups, policies and roles”">​</a></h1><p><strong>Learner status: not started. All supplied tasks on this page are mandatory in this learning path</strong>, including items originally labelled optional or bonus. Repeating tasks still require the stated action or comparison; reuse earlier resources and code where suitable, and record the new evidence. Source optional labels describe the original course only.</p><p><strong>Read first:</strong> <a href="./../../aws/iam-and-security.html">iam and security</a>.</p><h2 id="a02-1-—-groups-and-console-users" tabindex="-1"><span class="hub-section-number">1 </span>A02.1 — Groups and console users <a class="header-anchor" href="#a02-1-—-groups-and-console-users" aria-label="Permalink to “1 A02.1 — Groups and console users”">​</a></h2><ul><li>[ ] Create <code>CoordinatorsGroup</code>, <code>MentorsGroup</code> and <code>StudentsGroup</code>.</li><li>[ ] Create a console user for each group. Sign in before attaching policies and observe the initial lack of permissions.</li><li>[ ] Attach <code>AdministratorAccess</code>, <code>SupportUser</code> and <code>PowerUserAccess</code>, respectively. Recheck visible resources and allowed/denied operations under each user.</li></ul><h2 id="a02-2-—-policies-service-roles-and-named-profiles" tabindex="-1"><span class="hub-section-number">2 </span>A02.2 — Policies, service roles and named profiles <a class="header-anchor" href="#a02-2-—-policies-service-roles-and-named-profiles" aria-label="Permalink to “2 A02.2 — Policies, service roles and named profiles”">​</a></h2><ul><li>[ ] Create <code>EC2FullAccessPolicy</code>, <code>S3FullAccessPolicy</code> and <code>S3ReadOnlyAccessPolicy</code> with the source&#39;s EC2-wide, S3-wide and S3 read/list scopes. These broad lab policies are not production defaults.</li><li>[ ] Create EC2-trusted roles <code>EC2FullAccessRole</code>, <code>S3FullAccessRole</code>, <code>S3ReadOnlyAccessRole</code> and attach the corresponding policies.</li><li>[ ] Create <code>EC2FullAccessGroup</code>, <code>S3FullAccessGroup</code> and <code>S3ReadOnlyAccessGroup</code>; attach the matching policies.</li><li>[ ] Create exercise users with programmatic access, assign each to its group and configure separate CLI named profiles. Never commit their keys.</li><li>[ ] Compare allowed and denied operations through those profiles; retain actual outcomes, not just screenshots of policy attachment.</li></ul><h2 id="a02-3-—-cli-identity-management-—-promoted-from-optional-repeating-a02-1–2-through-cli" tabindex="-1"><span class="hub-section-number">3 </span>A02.3 — CLI identity management — promoted from optional; repeating A02.1–2 through CLI <a class="header-anchor" href="#a02-3-—-cli-identity-management-—-promoted-from-optional-repeating-a02-1–2-through-cli" aria-label="Permalink to “3 A02.3 — CLI identity management — promoted from optional; repeating A02.1–2 through CLI”">​</a></h2><ul><li>[ ] With an authorized admin profile, create a group, attach a managed policy, create a user and assign membership through CLI.</li><li>[ ] Complete the supplied IAM guide&#39;s bonus: create exercise access credentials, inspect the result and remove the temporary keys, policy attachment, group membership, user and group in a valid dependency order.</li><li>[ ] Keep required roles/profiles for later labs; remove disposable bonus identities and record what remains.</li></ul><h2 id="completion-evidence" tabindex="-1"><span class="hub-section-number">4 </span>Completion evidence <a class="header-anchor" href="#completion-evidence" aria-label="Permalink to “4 Completion evidence”">​</a></h2><ul><li>[ ] Record observed results for every section, including all promoted extensions.</li><li>[ ] Retain configuration/code, successful and denied/failing cases where specified, and actual cleanup state.</li><li>[ ] Link earlier evidence for repeating work and add the new interface/behavior comparison.</li></ul><p>Use the <a href="./#evidence-for-every-required-module">shared evidence rules</a>; never claim screenshots or sample code complete independent work.</p>',12)])])}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
